protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    // Preserve "Discriminator" property name for existing documents (EF Core 9 defaults to "$type")
    modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

    // Preserve "Blog|key" id format for existing documents (EF Core 9 defaults to key-only)
    modelBuilder.Entity<Blog>().HasRootDiscriminatorInJsonId(true);

    // HasIndex removed — Cosmos DB provider now throws instead of silently ignoring.
    // Manage indexing via the container's indexing policy (Azure Portal, Bicep, or Terraform).
}

